// ../services-definitions/build/index.js
function defineService(id) {
  return id;
}
function implementService(_, factory) {
  return factory;
}
implementService.withConfig = function() {
  return function(_, factory) {
    return factory;
  };
};

// src/core-services/provide-component/definition.ts
var ProvideComponentServiceDefinition = defineService("core:provide-component");

// ../services-definitions/build/core-services/signals/definition.js
var SignalsServiceDefinition = defineService("core:signals");

// src/core-services/provide-component/service.ts
var ProvideComponentServiceFactory = implementService(
  ProvideComponentServiceDefinition,
  ({ config, getService }) => {
    const { signal } = getService(SignalsServiceDefinition);
    const topComponents = signal(
      config.topComponents || []
    );
    const bottomComponents = signal(
      config.bottomComponents || []
    );
    const addTopComponent = (Comp) => {
      topComponents.set([...topComponents.get(), Comp]);
    };
    const addBottomComponent = (Comp) => {
      bottomComponents.set([...bottomComponents.get(), Comp]);
    };
    return {
      addTopComponent,
      addBottomComponent,
      getAllTopComponents: () => topComponents.get(),
      getAllBottomComponents: () => bottomComponents.get()
    };
  }
);
export {
  ProvideComponentServiceDefinition,
  ProvideComponentServiceFactory
};
